import{_ as e,o as a,c as i,ae as n}from"./chunks/framework.Bs_1Tt6f.js";const d=JSON.parse('{"title":"Equivalents Management","description":"","frontmatter":{},"headers":[],"relativePath":"docs/equivalents.md","filePath":"docs/equivalents.md"}'),r={name:"docs/equivalents.md"};function o(s,t,l,c,h,u){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="equivalents-management" tabindex="-1">Equivalents Management <a class="header-anchor" href="#equivalents-management" aria-label="Permalink to &quot;Equivalents Management&quot;">​</a></h1><p>The <strong>Transcription Equivalents</strong> view is where you organize and map abstract transcription patterns to your standardized Reference IDs for each specific manuscript.</p><h2 id="selecting-a-manuscript" tabindex="-1">Selecting a Manuscript <a class="header-anchor" href="#selecting-a-manuscript" aria-label="Permalink to &quot;Selecting a Manuscript&quot;">​</a></h2><p>When you open the Equivalents view, you will not see a list of patterns immediately. Instead, you see a list of <strong>Manuscript Sources</strong> extracted from your transcription data.</p><ol><li>Browse or search for the specific manuscript you want to manage.</li><li>The table shows whether a manuscript has been &quot;annotated&quot; (has assigned patterns) or is &quot;Not Started&quot;.</li><li>Click on a manuscript row (or the &quot;Edit&quot; button) to open its specific Pattern Editor.</li></ol><h2 id="the-pattern-editor" tabindex="-1">The Pattern Editor <a class="header-anchor" href="#the-pattern-editor" aria-label="Permalink to &quot;The Pattern Editor&quot;">​</a></h2><p>Once inside a manuscript&#39;s editor, the interface is split into two panels:</p><h3 id="_1-left-panel-available-patterns" tabindex="-1">1. Left Panel: Available Patterns <a class="header-anchor" href="#_1-left-panel-available-patterns" aria-label="Permalink to &quot;1. Left Panel: Available Patterns&quot;">​</a></h3><p>This panel lists every unique musical pattern found in the transcription data for this specific manuscript.</p><ul><li>Use the <strong>Sort</strong> dropdown to order patterns by frequency, alphabetical order, or length.</li><li>Use the <strong>Search</strong> bar to quickly find a specific string (e.g., <code>*dd</code>).</li><li>Click on any pattern in the list to add it to your active table on the right.</li></ul><h3 id="_2-right-panel-active-table" tabindex="-1">2. Right Panel: Active Table <a class="header-anchor" href="#_2-right-panel-active-table" aria-label="Permalink to &quot;2. Right Panel: Active Table&quot;">​</a></h3><p>This table shows the patterns you have selected to manage for this manuscript.</p><ul><li><strong>ID</strong>: The Reference ID you wish to assign to this pattern in this manuscript.</li><li><strong>Pattern</strong>: A visual rendering of the transcription string.</li><li><strong>Frequency</strong>: How many times this specific pattern occurs within this manuscript.</li><li><strong>Actions</strong>: Contains a button to open the <strong>Gallery</strong> (to preview the physical occurrences) or remove the pattern from your active list.</li></ul><h2 id="setting-reference-ids" tabindex="-1">Setting Reference IDs <a class="header-anchor" href="#setting-reference-ids" aria-label="Permalink to &quot;Setting Reference IDs&quot;">​</a></h2><p>By default, the ID you type into the &quot;ID&quot; column applies <strong>only to the current manuscript</strong>. This allows you to handle manuscript-specific graphical variations easily.</p><h3 id="the-global-id-button-★" tabindex="-1">The Global ID Button (★) <a class="header-anchor" href="#the-global-id-button-★" aria-label="Permalink to &quot;The Global ID Button (★)&quot;">​</a></h3><p>If you determine that a pattern should use a specific Ref ID across <em>all</em> manuscripts in your project, enter the ID and click the <strong>★ (Star)</strong> icon next to the input field.</p><p>This promotes the ID to a <strong>Global Default</strong>. In the future, whenever you add this pattern to another manuscript, the tool will automatically pre-fill the ID field with your Global Default, saving you time while still allowing you to overwrite it if that specific manuscript differs.</p>',18)])])}const f=e(r,[["render",o]]);export{d as __pageData,f as default};
